// Importa nel foglio Spettacoli quanto ricavato dall'Elenco Ordini Eventi:
//  - eventi MANCANTI → nuove righe (una per giorno, le successive come repliche)
//  - eventi presenti → contatti compagnia, accordi, orari/ordine nelle note (via giornale, così
//    tutti i dispositivi si allineano). Le date sbagliate le corregge correggiDateDST().
// importaElencoEventi(true) = prova (solo log). importaElencoEventi() = scrive.
function importaElencoEventi(dry) {
  var props = PropertiesService.getScriptProperties();
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheetByName('Spettacoli');
  var rows = sh.getDataRange().getValues();
  var hdr = rows[0].map(function(h){ return String(h).trim().toUpperCase(); });
  ['CONTATTI_JSON', 'ACCORDI'].forEach(function(c){ if (hdr.indexOf(c) < 0) { if (!dry) sh.getRange(1, hdr.length + 1).setValue(c); hdr.push(c); } });
  var col = function(n){ return hdr.indexOf(n); };
  var esistenti = {};
  for (var r = 1; r < rows.length; r++) {
    var d = rows[r][col('DATA')]; if (d instanceof Date) d = Utilities.formatDate(d, 'Europe/Rome', 'yyyy-MM-dd');
    esistenti[String(d) + '|' + String(rows[r][col('CITTA')]).toUpperCase() + '|' + String(rows[r][col('SPETTACOLO')]).toUpperCase()] = true;
  }
  var tdb = JSON.parse(props.getProperty('teatriDB') || '{}');
  var manif = JSON.parse(props.getProperty('manifCustom') || '[]');
  var nuove = [], remaps = [], base = Date.now(), k = 0, aggiornati = 0, saltati = 0;
  function riga(it, data, id, replicaOf, nota) {
    var o = [];
    o[col('ID')] = id; o[col('DATA')] = data; o[col('CITTA')] = it.citta; o[col('TEATRO')] = it.teatro;
    o[col('SPETTACOLO')] = it.spett; o[col('MANIFESTAZIONE')] = it.manif;
    ['N.MACC','SUB.MACC','N.ELETT','SUB.ELETT','N.FACC','SUB.FACC','N.FONI','SUB.FONI','N.SART','SUB.SART','TOTALE'].forEach(function(c){ if (col(c) >= 0) o[col(c)] = 0; });
    ['TAR.MACC','TAR.ELETT','TAR.FACC','TAR.FONI','TAR.SART'].forEach(function(c){ if (col(c) >= 0) o[col(c)] = ''; });
    o[col('NOTE')] = nota; o[col('FATTURATO')] = 'NO'; o[col('PREMONTAGGIO')] = 'NO';
    o[col('COLLAB_JSON')] = ''; o[col('REPLICA_OF')] = replicaOf || ''; o[col('MAILS_JSON')] = '';
    o[col('CONTATTI_JSON')] = it.contatti.length ? JSON.stringify(it.contatti) : ''; o[col('ACCORDI')] = it.accordi || '';
    for (var z = 0; z < hdr.length; z++) if (o[z] === undefined) o[z] = '';
    return o;
  }
  IMPORT_EVENTI.forEach(function(it) {
    if (it.stato !== 'MANCANTE') {
      (it.gf_ids || []).forEach(function(id){ remaps.push({ tipo: 'campi', id: String(id), note_add: it.note_add, accordi: it.accordi, contatti: it.contatti }); aggiornati++; });
      return;
    }
    var key = it.data + '|' + it.citta + '|' + it.spett.toUpperCase();
    if (esistenti[key]) { saltati++; return; }
    var giorni = [];
    var d0 = new Date(it.data + 'T12:00:00'), d1 = new Date(it.data_fine + 'T12:00:00');
    for (var t = new Date(d0); t <= d1; t.setDate(t.getDate() + 1)) giorni.push(Utilities.formatDate(t, 'Europe/Rome', 'yyyy-MM-dd'));
    var nota = it.note_add + (it.repliche > giorni.length ? (it.note_add ? ' | ' : '') + it.repliche + ' repliche' : '');
    var mainId = base + (k++) * 1000;
    nuove.push(riga(it, giorni[0], mainId, '', nota));
    for (var g = 1; g < giorni.length; g++) nuove.push(riga(it, giorni[g], mainId + g, mainId, nota));
    if (!tdb[it.citta]) tdb[it.citta] = [];
    if (tdb[it.citta].indexOf(it.teatro) < 0) tdb[it.citta].push(it.teatro);
    if (it.manif && manif.indexOf(it.manif) < 0) manif.push(it.manif);
  });
  Logger.log('Nuove righe: ' + nuove.length + ' (eventi mancanti, repliche incluse) | aggiornamenti su righe esistenti: ' + aggiornati + ' | già presenti saltati: ' + saltati);
  if (dry) { Logger.log('PROVA: nulla scritto. Prime 5 nuove: ' + JSON.stringify(nuove.slice(0, 5).map(function(o){ return [o[col('DATA')], o[col('CITTA')], o[col('TEATRO')], o[col('SPETTACOLO')], o[col('MANIFESTAZIONE')]]; }))); return; }
  if (nuove.length) sh.getRange(sh.getLastRow() + 1, 1, nuove.length, hdr.length).setValues(nuove);
  Object.keys(tdb).forEach(function(c){ tdb[c].sort(); });
  props.setProperty('teatriDB', JSON.stringify(tdb));
  props.setProperty('manifCustom', JSON.stringify(manif.sort()));
  var res = remaps.length ? applicaAnagrafica(remaps) : { righe: 0, ver: '-' };
  props.setProperty('lastModified', String(Date.now()));
  Logger.log('SCRITTO: ' + nuove.length + ' righe nuove; ' + res.righe + ' righe aggiornate (giornale v' + res.ver + '). Nell\'app: Scarica da Sheets, poi Config → Verifica anagrafica per uniformare i nomi.');
}
